		&nodeCfg.Stages.Exit.StageBase,
	}

	for _, stage := range stages {
		for i, exec := range stage.Execs {
			execCopy := *exec
			execCopy.Command = r.Replace(exec.Command)
			stage.Execs[i] = &execCopy
		}
	}
}

